package com.haucheng.erp.controller;
import com.haucheng.erp.auth.RequirePermission; import com.haucheng.erp.common.*; import com.haucheng.erp.dto.ProductRequest; import com.haucheng.erp.service.ProductService; import com.haucheng.erp.vo.ProductView; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/master-data/products") @RequiredArgsConstructor @RequirePermission("system.product.view") public class ProductController { private final ProductService service;
 @GetMapping public ApiResponse<PageResult<ProductView>> page(@RequestParam(required=false) String code,@RequestParam(required=false) String name,@RequestParam(required=false) Long categoryId,@RequestParam(required=false) Long brandId,@RequestParam(required=false) String model,@RequestParam(required=false) Boolean status,@RequestParam(required=false) String productType,@RequestParam(required=false) Integer page,@RequestParam(required=false) Integer size){return ApiResponse.success(service.getPage(code,name,categoryId,brandId,model,status,productType,page,size));}
 @GetMapping("/{id}") public ApiResponse<ProductView> get(@PathVariable Long id){return ApiResponse.success(service.getById(id));} @PostMapping @RequirePermission("system.product.create") public ApiResponse<ProductView> create(@Valid @RequestBody ProductRequest r){return ApiResponse.success(service.create(r));} @PutMapping("/{id}") @RequirePermission("system.product.update") public ApiResponse<ProductView> update(@PathVariable Long id,@Valid @RequestBody ProductRequest r){return ApiResponse.success(service.update(id,r));}
 @PostMapping("/{id}/enable") @RequirePermission("system.product.disable") public ApiResponse<Void> enable(@PathVariable Long id){service.updateStatus(id,true);return ApiResponse.success();} @PostMapping("/{id}/disable") @RequirePermission("system.product.disable") public ApiResponse<Void> disable(@PathVariable Long id){service.updateStatus(id,false);return ApiResponse.success();}
}
